  'about.council.sub':
    'DOGYPT wird von Menschen gebaut, die wissen, was ein Hund bedeutet. Wenn du etwas einzubringen hast — eine Fähigkeit, eine Stimme, eine Vision — dann gehört es hierher.',
  'about.council.rolesAria': 'Wähle deine Rolle',
