  "payment.transparency.title": "100% Transparenz",
  "payment.transparency.hint": "Tippe auf eine Kategorie für Details.",
  "payment.transparency.eyebrow": "Wohin geht das Geld?",
  "transparency.part.development": "Entwicklung",
  "transparency.part.affiliate": "Gemeinschaft",
  "transparency.part.directHelp": "Rettung",
  "transparency.part.hekthorBowl": "Hekthors Napf",
  "transparency.part.development.note": "Die Nation aufbauen und alles finanzieren, worauf sie läuft — die Menschen, die DOGYPT in Bewegung halten, und die Dienste, Werkzeuge und Server dahinter. Das ist der Motor der Bewegung, und jede einzelne Ausgabe wird dokumentiert und offen veröffentlicht.",
  "transparency.part.affiliate.note": "Keine Werbung — Menschen. Das geht direkt auf die Konten der Dogyptier, die den Glauben verbreiten, ausgezahlt in BONES, die sie später in DOGYPT ausgeben oder Hunden in Not spenden können. Wir investieren ins Rudel, nie in teures Marketing — das Rudel trägt das Wort viel weiter.",
  "transparency.part.directHelp.note": "Direkt zu Hunden in Not — Tierheime, Futter, Tierarztrechnungen und Rettungsmissionen. Keine Mittelsmänner, keine Verwaltungskosten: Dieser Anteil geht dorthin, wo das Leid ist, und jeder einzelne Cent wird dokumentiert, belegt und für das ganze Rudel öffentlich gemacht.",
  "transparency.part.hekthorBowl.note": "Der Gründerhund, mit dem alles begann. Dieser Anteil ist eine transparente Belohnung für Hekthor und sein Herrchen — schlicht ihr Gehalt. Ihr Ziel ist es, Millionäre zu werden — eine Million Hunde im Rudel. Ohne Hekthor gäbe es DOGYPT nicht — dieser Napf ist ein Dankeschön.",
  "legal.eyebrow": "DOGYPT · Legal",
  "legal.motto": "DOGYPT · Wir glauben an den Hund",
  "about.council.formTitle": "Teil der Mission werden",
  "about.council.consent": "Mit dem Absenden stimme ich zu, E-Mails von DOGYPT zu erhalten — keine Werbung, nur Mobilisierung des Rudels und Kommunikation.",
  "about.footer.motto": "Wir glauben an den Hund.",

