  'heroglyph.sales.pricePill': 'Einmalig €11 · dein Eintritt',
  'heroglyph.sales.card.cert.title': 'Zertifikat',
  'heroglyph.sales.card.cert.note': 'PDFs mit einzigartigem Design',
