  'heroglyph.sales.why': 'Warum €11?',
  'heroglyph.sales.eyebrow': 'Dein Ticket nach DOGYPT',
  'heroglyph.sales.title': 'Heroglyph',
  'heroglyph.sales.subtitle': 'Ein einzigartiges Symbol, das dich und deinen Hund beschreibt — eure ewige Verbindung.',
  'heroglyph.sales.loading': 'Dein Heroglyph wird geladen…',
  'heroglyph.sales.cta': 'Heroglyph erstellen',
  'heroglyph.sales.back': 'Zurück',
  'heroglyph.sales.transparency.title': '100% Transparenz',
  'heroglyph.sales.transparency.tribute': 'Dein Eintritt — €11, einmalig',
  'heroglyph.sales.transparency.footer': 'Jeder Euro bleibt sichtbar, für jedes Mitglied einsehbar. Du bezahlst kein Unternehmen — du nährst das Rudel.',
  'entry.declare.eyebrow': 'Hiermit erkläre ich',
  'entry.title': 'In Dog I Trust',
  'entry.subtitle': 'Das ist kein Scherz. Jede ernsthafte Religion muss diese Dinge erklären.',
  'entry.criteria.theology.title': 'Theologie',
  'entry.criteria.theology.body': 'Bester Freund, Wächter, Lehrer, Partner in jedem Abenteuer. Der Hund schenkt Liebe ohne Bedingungen — und an seiner Seite zu gehen macht uns menschlicher.',
  'entry.criteria.canon.title': 'Kanon',
  'entry.criteria.canon.body': 'Jeder Glaube hat seine Schrift. Unsere ist DOGMA: unsere Verbindung zum Hund, niedergeschrieben in zwölf Kapiteln, frei zu lesen auf dogma.dogypt.com.',
  'entry.criteria.community.title': 'Gemeinschaft',
  'entry.criteria.community.body': 'Wir sind Hundeliebhaber mit einem Ziel. Allein kann jeder von uns wenig bewirken — gemeinsam kennt unsere Kraft keine Grenze.',
  'entry.criteria.symbol.title': 'Symbol',
  'entry.criteria.symbol.body': 'Jeder Glaube hat sein Zeichen. Unseres ist der Heroglyph: ein einzigartiges heiliges Zeichen für jeden Hund, in jeder Sprache verstanden, überall.',
  'entry.criteria.ritual.title': 'Ritual',
  'entry.criteria.ritual.body': 'Der Spaziergang. Tägliche Therapie, die Körper und Geist in guter Verfassung hält — und die Seele auch. Das älteste Ritual, das wir längst befolgen, ohne dass man es uns sagen muss.',
  'entry.criteria.vision.title': 'Vision',
  'entry.criteria.vision.body': 'Die Verbindung zwischen Mensch und Hund zu erheben — und für den Respekt und das bessere Leben zu kämpfen, das jedem Hund zusteht.',
  'entry.criteria.offerings.title': 'Opfergaben',
  'entry.criteria.offerings.note': '(ein symbolischer Tribut)',
  'entry.criteria.offerings.pill': '€11 · einmalig',
  'entry.criteria.offerings.tag': '100 % Transparenz',
  'entry.criteria.offerings.body': '€11, einmal. Eine symbolische Opfergabe — jede Einnahme und jede Ausgabe in einem Kontobuch, das allen offensteht. Die Energie, die uns am Leben hält.',
  'entry.criteria.legitimacy.title': 'Legitimität',
  'entry.criteria.legitimacy.pill': 'Noch {count} Mitglieder',
  'entry.criteria.legitimacy.body': 'Eintausend Gründer, und wir sind stark genug, um uns als Nation registrieren zu lassen, die das Gesetz anerkennen muss. Die letzte Marke — nur du kannst sie erreichen.',
