  "heroglyph.flow.more.ainubis.d": "Unsere personalisierte KI, dein Helfer und Mentor. Sie kennt deinen Hund in- und auswendig. Lerne aus ihren Quellen, schau hinein und steuere eigene Materialien und Erfahrungen bei.",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT macht Hundeliebhabern das Leben leichter, bringt aber auch gute Menschen zusammen und hilft Hunden in Not — völlig transparent. Sogar der Gründer von DOGYPT, HEKTHOR, kommt aus dem Tierheim.",
  "heroglyph.flow.more.cause.t": "HÖHERES ZIEL",
  "heroglyph.flow.more.close": "Schließen",
  "heroglyph.flow.more.dogid.d": "Das komplette Profil deines Hundes an einem Ort. Was du ausfüllst, nutzt unser AINUBIS. Ein praktisches „Zeugnis“, immer griffbereit, zum Beispiel beim Tierarzt.",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "Hundefreundliche Abenteuer aus aller Welt an einem Ort. Füge deinen Lieblingsausflug hinzu und teile ihn mit dem Rudel. Lass dich von anderen inspirieren, sammle Punkte, Abzeichen und Levels.",
  "heroglyph.flow.more.dogtrip.t": "DOGTRIP",
  "heroglyph.flow.more.eyebrow": "DOGYPT-Mitgliedschaft",
  "heroglyph.flow.more.glyph.d": "Ein einzigartiges Symbol, das deinen Hund perfekt einfängt. Eine universelle Sprache, die Hundeliebhaber vereinen soll. Dein Schlüssel zu DOGYPT.",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "Von jeden €11 gehen €5 in die Entwicklung, €3 an die Gemeinschaft, €2 in die Rettung von Hunden und €1 in Hekthors Napf. Jede Ausgabe wird dokumentiert und veröffentlicht.",
  "heroglyph.flow.more.money.t": "WOHIN DAS GELD GEHT",
  "heroglyph.flow.more.next": "Weiter",
  "heroglyph.flow.more.pack.d": "Zugang zu einer Plattform, gebaut für Hundeliebhaber. Die App wächst ständig weiter und wird Hundeliebhabern in jeder Hinsicht dienen.",
  "heroglyph.flow.more.pack.t": "MITGLIEDERBEREICH",
  "heroglyph.flow.more.prev": "Zurück",
  "heroglyph.flow.more.sniffer.d": "Finde einen Kumpel, ein Paar oder eine Gruppe für Ausflüge, regelmäßige Gassirunden oder ein Roadtrip-Abenteuer. Eine Partnerbörse speziell für Hunde und ihre Menschen.",
  "heroglyph.flow.more.sniffer.t": "SNIFFER",
  "pack.buddy.intro": "Finde Kumpels, mit denen du die Welt erschnüffelst.",
  "heroglyph.flow.stay.done.cta": "Wand ansehen",
  "heroglyph.flow.stay.done.guest": "AINUBIS sieht sich das Foto an, und in ein paar Minuten ist dein Hund an der Wand. Deinen Heroglyph heben wir auf — beitreten kannst du jederzeit.",
  "heroglyph.flow.stay.done.support": "Danke für deinen Beitrag. AINUBIS sieht sich das Foto an, und in ein paar Minuten ist dein Hund mit deiner Botschaft an der Wand.",
  "heroglyph.flow.stay.done.t": "Fertig.",
