  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. Innerhalb des Rudels: Was andere Mitglieder sehen",
  "privacy.s12.body": "Abschnitt 3 beschreibt das öffentliche GodsGrid. Innerhalb des Rudels — im Mitgliederbereich — sehen andere eingeloggte Mitglieder mehr: deinen Vornamen, deine Dogyptier-Nummer, den Namen und das Foto deines Hundes, die Eigenschaften, die du zu deinem Hund ausgefüllt hast, die Ausflüge, die du eingetragen oder angekündigt hast, deine Bewertungen und Kommentare und alles, was du auf deinem Profil geschrieben hast. Sie sehen nicht deine E-Mail-Adresse, deine Postanschrift, deine Zahlungsdaten oder deine Nachrichten mit anderen. Wenn du einen Ausflug als offen ankündigst, werden Route, Datum und dein Hund für jedes Mitglied sichtbar, damit es um Teilnahme bitten kann — genau das bedeutet Ankündigen. Ein Ausflug, den du privat hältst, sehen nur du und die Leute, die schon mitgehen. Du entscheidest, welche der beiden Optionen es ist, und kannst das jederzeit ändern.",
  "privacy.s13.title": "13. Nachrichten & Meldungen",
  "privacy.s13.body": "Private Nachrichten zwischen Mitgliedern werden in unserer Datenbank (Supabase) gespeichert, damit Gespräche über mehrere Sitzungen hinweg erhalten bleiben. Rechtsgrundlage: Art. 6 Abs. 1 lit. b DSGVO — sie sind Teil der Mitgliedschaft, die du bezahlt hast. Wir lesen sie nicht routinemäßig und nutzen sie nie für Werbung oder Profiling. Wir öffnen ein Gespräch nur, wenn es gemeldet wird, wenn wir einen konkreten Missbrauchs- oder Sicherheitsvorfall untersuchen, oder wenn das Gesetz es verlangt. Eine Meldung speichert den von dir gewählten Grund, deine optionale Notiz und einen Verweis auf das Gemeldete — nicht eine eigene Kopie davon. Blockieren wird als Paar von Mitglieds-Kennungen gespeichert. Löschst du dein Konto, verschwinden deine Nachrichten mit ihm; die Kopie im Thread der anderen Person bleibt erhalten, angezeigt als von einem entfernten Mitglied, weil dieses Gespräch auch ihr gehört.",
  "terms.s12.title": "12. Inhalte, die du veröffentlichst",
  "terms.s12.body": "Neben deinem HEROGLYPH kannst du im Rudel Inhalte veröffentlichen: Ausflugsfotos, Routen und Orte, Ausflugsbeschreibungen, Bewertungen, Kommentare und Fragen und alles, was du auf deinem Profil schreibst. Markierst du einen Ausflug als gegangen, sehen andere Mitglieder deinen Vornamen und die Hunde, die ihn mit dir gegangen sind. Du behältst das Eigentum an allem, was du veröffentlichst. Mit der Veröffentlichung räumst du der DOGYPT s.r.o. eine weltweite, gebührenfreie, nicht-exklusive Lizenz ein, diesen Inhalt zu speichern, anzuzeigen und anzupassen, um den Dienst zu betreiben und zu bewerben — zum Beispiel dein Ausflugsfoto auf der Karte, in einer Ausflugsliste oder auf einer Share-Karte zu zeigen. Die Lizenz gilt, solange der Inhalt im Dienst ist; entfernst du den Inhalt oder dein Konto, endet sie, außer bei Backups, die nach ihrem normalen Zyklus auslaufen. Wir verkaufen deine Inhalte nicht und lizenzieren sie niemand anderem zur eigenen Nutzung. Veröffentliche nur, wozu du das Recht hast — das gilt auch für Fotos, die jemand anderes gemacht hat, und Personen, die darauf erkennbar sind.",
  "terms.s13.title": "13. Nachrichten zwischen Mitgliedern",
  "terms.s13.body": "Mitglieder können sich direkt schreiben. Nachrichten sind privat zwischen den Beteiligten — wir lesen sie nicht routinemäßig und nutzen sie nie für Werbung. Sie werden auf unseren Servern gespeichert, damit das Gespräch bei deiner Rückkehr noch da ist, und wir können ein Gespräch in drei Fällen lesen: wenn es jemand meldet, wenn wir einen konkreten Missbrauchs- oder Sicherheitsvorfall untersuchen, oder wenn das Gesetz es verlangt. Du kannst ein anderes Mitglied jederzeit blockieren; das Blockieren wirkt sofort und in beide Richtungen. Behandle Nachrichten wie jedes andere Online-Gespräch — schick keine Zahlungsdaten, Passwörter oder Dokumente, die du nicht gespeichert haben willst.",
  "terms.s14.title": "14. Melden & Moderation",
  "terms.s14.body": "Profile, Ausflüge und Gespräche können gemeldet werden. Eine Meldung geht an uns, und ein Mensch liest sie — heute ist das der Gründer Matej Stacho. Wir wollen uns jede Meldung innerhalb von 7 Tagen ansehen. Je nach Befund tun wir nichts, entfernen den Inhalt, verwarnen das Mitglied, schränken ein, was es posten darf, oder schließen das Konto. Greifen wir in deinen Inhalt ein, teilen wir dir den Grund per E-Mail mit, und du kannst antworten und widersprechen. Wir können Inhalte auch aus eigener Initiative entfernen, wenn sie Abschnitt 7 verletzen. Vorsätzlicher oder wiederholter Missbrauch — Belästigung, Spam, gefälschte Ausflüge, Inhalte mit Minderjährigen — beendet das Konto ohne weitere Warnung.",
  "about.legends.titleFilm": "HUNDE LIEBT JEDER",
  "about.legends.subFilm": "Es ist das Eine, worauf sich dieser ganze Planet schon einigt. Und niemand hat je etwas damit gemacht.",
