  "pack.cal.life.noBirth": "Die Lebensachse braucht ein Geburtsdatum. Trag es in das DOG ID des Hundes ein, und das Raster zeichnet sich ab Woche eins.",
  "pack.cal.life.srcNone": "Durchschnittliche Lebenserwartung: Wir kennen Rasse und Gewicht noch nicht, also stützt sich die Schätzung auf die mittlere Größenklasse. Trag die Rasse im DOG ID ein.",
  "pack.cal.life.srcPre": "Durchschnittliche Lebenserwartung:",
  "pack.cal.life.years": "Jahre",
  "pack.cal.life.srcBreed": "veröffentlichter Rassewert",
  "pack.cal.life.srcWeight": "Schätzung nach Gewicht",
  "pack.cal.life.bandNote": "Das ist der Durchschnitt von Tausenden Hunden, keine Vorhersage für diesen einen.",
  "pack.cal.life.srcRefBreed": "Quelle: veröffentlichte Spanne eines Rasseclubs (AKC / The Kennel Club).",
  "pack.cal.life.srcRefWeight": "Quelle: tierärztliche Erhebungen zur Lebenserwartung nach Gewicht (UK VetCompass / RVC life tables).",
  "pack.cal.life.tgtPre": "Ziel:",
  "pack.cal.life.tgtBody": "bis zu fünf zusätzliche Jahre, die ganzheitliche Fürsorge dazugeben kann — schlank bleiben, Bewegung im Gelände, Zähne, Schlaf und so wenig unnötige Chemie wie möglich.",
  "pack.cal.life.tgtSrc": "Eine grobe Schätzung, kein Versprechen. Nur ein Teil davon ist gemessen: allein das Schlankbleiben brachte Labradoren 1,8 Jahre (Purina Life Span Study, JAVMA 2002).",
  "pack.cal.life.intro": "Unten siehst du das ganze Leben deines Hundes in Blöcken. Ein Block = eine Woche, eine Zeile = ein Jahr. Auf der einen Seite ist das beunruhigend, auf der anderen genau die Erinnerung, jeden Moment zu nutzen und nichts aufzuschieben.",
  "pack.cal.life.fromBirth": "Gezählt ab der Geburt",
  "pack.cal.life.daysLived": "Tage des besten Lebens",
