  "pack.cal.life.zone": "Hierher haben es nur wenige Hunde in der Geschichte geschafft",
  "pack.cal.life.recTitle": "Hundelangwierigkeit ist kein Zufall",
  "pack.cal.life.recSub": "Unten findest du ein paar Rekordhalter, die fast 30 Jahre alt wurden. Ein langes, glückliches Leben beruht vor allem auf deinen täglichen Entscheidungen.",
  "pack.cal.life.recPrev": "Vorheriger",
