  "pack.cal.life.tipsTitle": "Was du dagegen tun kannst",
  "pack.cal.life.tipsSub": "Sechs Dinge, die mehr zählen als die Rasse. Keines kostet Geld, alle kosten Aufmerksamkeit.",
  "pack.cal.life.protoTitle": "Longevity-Protokoll",
  "pack.cal.life.protoBody": "Der ganze Ablauf, auf dem diese paar Tipps beruhen — Ernährung, Belastung, Ruhe und was gemessen werden sollte. Er wird in einer Datenbank leben, die ",
  "pack.cal.life.protoSoon": "bewacht",
