  "pack.cal.life.recSince": "seit {year}",
  "pack.cal.life.tip.weight.title": "Schlank bleiben ist das Einzige, was bewiesen ist",
  "pack.cal.life.tip.weight.body": "Von allem, was man für einen Hund tun kann, hat eine Sache den härtesten Beleg für die Lebensdauer: ihn nicht zunehmen lassen. Der Unterschied zwischen einem schlanken und einem leicht übergewichtigen Hund sind Jahre, keine Monate. Man sollte die Rippen ohne Druck fühlen können.",
  "pack.cal.life.tip.move.title": "Bewegung auf echtem Gelände, nicht eine Runde um den Block",
  "pack.cal.life.tip.move.body": "Unebener Boden hält Gelenke, Muskeln und Kopf gefordert. Jeder Ausflug, den du einträgst, wird auf diesem Raster zu einer dunklen Woche — und dunkle Wochen sind das Einzige, was du wirklich beeinflussen kannst.",
  "pack.cal.life.tip.food.title": "Futter, das ein Hund als Nahrung erkennt",
  "pack.cal.life.tip.food.body": "Je weniger Schritte zwischen der Rohzutat und dem Napf liegen, desto weniger kann auf dem Weg schiefgehen. Trockenfutter ist keine Sünde, aber auch keine Ernährung — es ist eine Abkürzung.",
  "pack.cal.life.tip.chem.title": "Chemie nur, wenn sie wirklich nötig ist",
  "pack.cal.life.tip.chem.body": "Ganzjährige Entwurmungsmittel, Narkose aus Bequemlichkeit und Antibiotika „zur Sicherheit“ sind Entscheidungen, keine Routine. Frag bei jeder einzelnen: Was passiert, wenn ich es weglasse? Wo die Antwort „nichts“ ist, lass es weg.",
  "pack.cal.life.tip.stress.title": "Ruhe zählt genauso viel wie Bewegung",
  "pack.cal.life.tip.stress.body": "Ein Hund, der ständig wachsam ist, verbrennt den Körper von innen. Ungestörter Schlaf, ein vorhersehbarer Tag und Ruhe nach Belastung sind keine Faulheit — es sind die Stunden, in denen der Körper sich selbst reparieren kann.",
  "pack.cal.life.tip.protocol.title": "Ein Protokoll statt eines panischen Laufs zum Tierarzt",
  "pack.cal.life.tip.protocol.body": "Entwurmung, Koprologie und Blutwerte haben ihre eigenen Fenster im Kalender. Ein Hund, dessen Blut man zweimal im Jahr prüft, wird nicht behandelt — er wird davor bewahrt.",
  "pack.cal.life.tip.joints.title": "Gelenke werden angegangen, BEVOR sie zu schmerzen beginnen",
  "pack.cal.life.tip.joints.body": "Dein Hund ist jetzt in der Seniorenklasse. Die Gelenkkur hat ihr Fenster im Kalender ab November — nicht weil er hinkt, sondern damit er es nie muss.",
