  "pack.nature.bal.water.excess.loose-stool": "Weicher Stuhlgang",
  "pack.nature.bal.water.excess.lethargy": "Mattheit",
  "pack.nature.bal.water.excess.headaches": "Kopfschmerzen",
  "pack.nature.bal.water.excess.headaches.note": "Empfindlich bei Berührung am Kopf, oder drückt die Stirn gegen eine Wand",
  "pack.nature.bal.water.excess.stones": "Nieren- oder Blasensteine",
  "pack.nature.bal.water.excess.arthritis": "Arthritis",
  "pack.nature.bal.water.excess.tumors": "Tumore im Gehirn, an der Wirbelsäule oder im Unterbauch",
