  "pack.nature.intro.title": "Wer ist dein Hund?",
  "pack.nature.intro.body": "Zweiundzwanzig Fragen und eine Checkliste. Du erfährst, woraus dein Hund gemacht ist, welche Aufgabe er für deine Familie übernimmt und wohin sich seine Balance gerade neigt.",
