  "pack.nature.balance.title": "Ist gerade etwas los?",
  "pack.nature.balance.body": "Die Konstitution deines Hundes steht fürs Leben fest, kann aber aus der Balance kippen. Kreuz alles an, was zutrifft — so viel oder so wenig du willst.",
  "pack.nature.balance.none": "Nichts auf der Liste? Lass es leer und mach weiter — das ist die beste Antwort, die es gibt.",
  "pack.nature.progress": "Fortschritt",
  "pack.nature.special.eyebrow": "Noch vier — wir suchen besondere Rollen",
  "pack.nature.special.body": "Diese vier Rollen liegen über der Hauptrolle. Die meisten Hunde tragen keine davon — das ist normal.",
