  "pack.nature.ans.yes": "Ja",
  "pack.nature.ans.sometimes": "Manchmal",
  "pack.nature.ans.no": "Nein",
  "pack.network.ads.body": "Bezahlte Werbung ist ein sehr ineffizienter Weg, um neue Hundeliebhaber zu finden — und eine Art, unser Geld großen Konzernen hinzuwerfen. Es funktioniert viel besser, die Mitglieder der Bewegung direkt dafür zu belohnen, dass sie aktiv sind. Es gibt einen Haken: <strong style=\"font-weight:600\">es funktioniert wirklich nur, wenn du rausgehst und den Leuten um dich herum von uns erzählst</strong> :)",
  "pack.network.ads.header": "Warum dieser Weg?",
  "pack.network.ads.wordAd": "eine Anzeige",
  "pack.network.ads.wordScroll": "ein Fremder scrollt weiter",
  "pack.network.allBones": "Alle {n}",
  "pack.network.back": "Zurück",
  "pack.network.bonesLabel": "Deine BONES",
  "pack.network.bonesRate": "{n} BONES = 1 €",
  "pack.network.bonesUnit": "Bones",
  "pack.network.capHintLog": "Deckel 1:1 — ein Geschenk kann nur ausgleichen, was du schon gelebt hast.",
  "pack.network.capHintRow": "Deckel 1:1 — ein Geschenk gleicht aus, was du gelebt hast",
  "pack.network.capped.none": "Daraus keine Hingabe — deine Geschenke gleichen schon alles aus, was du gelebt hast. Die BONES gehen trotzdem durch. <i>Geld verdoppelt die Jahre, es ersetzt sie nie.</i>",
  "pack.network.capped.room": "Gedeckelt auf <b style=\"color:#2a1608\">{room}</b> — ein Geschenk kann nur ausgleichen, was du schon gelebt hast ({lived} Hingabe bisher). Die BONES gehen trotzdem durch; die Ehre wartet auf die Tage.",
  "pack.network.chainFirstInvite": "deine erste Einladung",
  "pack.network.chainJoined": "{n} beigetreten",
  "pack.network.chainWhoever": "wen auch immer sie mitbringen",
  "pack.network.chainYou": "du",
  "pack.network.close": "Schließen",
  "pack.network.confirmSend": "Bist du sicher? Einmal gesendet, verlassen die BONES deinen Kontostand — das lässt sich nicht zurücknehmen.",
  "pack.network.copyLinkAria": "Einladungslink kopieren",
  "pack.network.devotionWord": "Hingabe",
  "pack.network.emptyLine": "Noch niemand — der erste Name hier ist der Anfang deiner Linie.",
  "pack.network.eyebrow": "DOGYPT wächst durch dich",
  "pack.network.generatingLink": "Dein Link wird erzeugt…",
  "pack.network.linkFailed": "Dein Einladungslink konnte nicht geladen werden.",
  "pack.network.linkRetry": "Noch mal versuchen",
  "pack.network.groupDirect": "direkt",
  "pack.network.groupTheirBrings": "ihre Einladungen",
  "pack.network.inLine": "In deiner Linie",
  "pack.network.info.bones.body": "BONES ist die interne Währung von DOGYPT — ein spielerischer Name für eine reale Sache. Ein Hund zahlt in Knochen; wir auch. Du <b>verdienst</b> sie, indem du Hundeliebhaber ins Rudel bringst und die Bewegung voranbringst, und du <b>gibst</b> sie innerhalb von DOGYPT aus: Unterstützung von Tierheim-Sammlungen, Merch einlösen und später die Bezahlung anderer Dogyptier für das, was sie schaffen. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Was ist BONES?",
  "pack.network.info.why.body": "Eine Bewegung dieser Größe kann man nicht kaufen — kein Budget erreicht einen Fremden so, wie ein Dogyptier einen Freund erreicht. Also legt das Rudel die Belohnung dorthin, wo die Reichweite ist: zu dir. Wenn jemand über deinen Link beitritt, bekommst du <b>{l1} BONES</b>; bringt er jemanden mit, bekommst du <b>{l2}</b> mehr. Jeder Dogyptier, der das Wort verbreitet, ist kein Verkäufer — er ist ein Missionar, und diese Arbeit ehren wir.",
  "pack.network.info.why.cap": "Warum wir dich bitten",
  "pack.network.intro": "Eine Bewegung wächst nur, wenn ihre Mitglieder die Botschaft tragen und neue Leute mitbringen. Deshalb bitten wir dich direkt: <strong style=\"color:#2a1608;font-weight:600\">lade die Hundeliebhaber ein, die du kennst</strong>. Hier ist genau, wie es funktioniert.",
  "pack.network.inviteLinkHeader": "Dein Einladungslink",
  "pack.network.listSummary": "{n} Leute · {b} BONES verdient",
  "pack.network.noBonesYetHint": "Noch keine BONES — lade zuerst jemanden ein.",
