  "pack.network.step1Title": "Teil deinen Link",
  "pack.network.step2Body": "Wenn jemand über deinen Link einen <strong style=\"color:#2a1608;font-weight:600\">Heroglyph</strong> erschafft, bekommst du <strong style=\"color:#2a1608;font-weight:600\">{l1} BONES</strong>. Bringt dieses Mitglied auch jemanden, bekommt es {l1} und <strong style=\"color:#2a1608;font-weight:600\">du bekommst {l2}</strong> mehr.",
